/**
 * 力扣已经定义好了 TreeNode：
 * public class TreeNode {
 *     int val;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode() {}
 *     TreeNode(int val) { this.val = val; }
 *     TreeNode(int val, TreeNode left, TreeNode right) { this.val = val; this.left = left; this.right = right; }
 * }
 */
class Solution {
    public TreeNode buildTree(String data) {
        String[] vals = data.isEmpty() ? new String[0] : data.split(",");   // "1,2,null" -> ["1", "2", "null"]
        if (vals.length == 0 || vals[0].equals("null")) {
            return null;
        }
        TreeNode root = new TreeNode(Integer.parseInt(vals[0]));
        Deque<TreeNode> q = new ArrayDeque<>();             // 还没接孩子的节点
        q.offer(root);
        int i = 1;
        while (!q.isEmpty() && i < vals.length) {
            TreeNode node = q.poll();                       // 给它接左、右孩子
            if (!vals[i].equals("null")) {
                node.left = new TreeNode(Integer.parseInt(vals[i]));
                q.offer(node.left);
            }
            i++;
            if (i < vals.length && !vals[i].equals("null")) {
                node.right = new TreeNode(Integer.parseInt(vals[i]));
                q.offer(node.right);
            }
            i++;
        }
        return root;
    }
}

