/**
 * 力扣已经定义好了 TreeNode：
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
    TreeNode* buildTree(string data) {
        vector<string> vals;                                // "1,2,null" -> ["1", "2", "null"]
        stringstream ss(data);
        for (string s; getline(ss, s, ',');) {
            vals.push_back(s);
        }
        if (vals.empty() || vals[0] == "null") {
            return nullptr;
        }
        TreeNode* root = new TreeNode(stoi(vals[0]));
        queue<TreeNode*> q;                                 // 还没接孩子的节点
        q.push(root);
        size_t i = 1;
        while (!q.empty() && i < vals.size()) {
            TreeNode* node = q.front();                     // 给它接左、右孩子
            q.pop();
            if (vals[i] != "null") {
                node->left = new TreeNode(stoi(vals[i]));
                q.push(node->left);
            }
            i++;
            if (i < vals.size() && vals[i] != "null") {
                node->right = new TreeNode(stoi(vals[i]));
                q.push(node->right);
            }
            i++;
        }
        return root;
    }
};

