/**
 * 力扣已经定义好了 TreeNode：
 * type TreeNode struct {
 *     Val   int
 *     Left  *TreeNode
 *     Right *TreeNode
 * }
 */
func buildTree(data string) *TreeNode {
	var vals []string // "1,2,null" -> ["1", "2", "null"]
	if data != "" {
		vals = strings.Split(data, ",")
	}
	if len(vals) == 0 || vals[0] == "null" {
		return nil
	}
	v, _ := strconv.Atoi(vals[0])
	root := &TreeNode{Val: v}
	q := []*TreeNode{root}        // 还没接孩子的节点
	i := 1
	for len(q) > 0 && i < len(vals) {
		node := q[0] // 给它接左、右孩子
		q = q[1:]
		if vals[i] != "null" {
			v, _ := strconv.Atoi(vals[i])
			node.Left = &TreeNode{Val: v}
			q = append(q, node.Left)
		}
		i++
		if i < len(vals) && vals[i] != "null" {
			v, _ := strconv.Atoi(vals[i])
			node.Right = &TreeNode{Val: v}
			q = append(q, node.Right)
		}
		i++
	}
	return root
}

