/**
 * 力扣已经定义好了 TreeNode：
 * function TreeNode(val, left, right) {
 *     this.val = (val === undefined ? 0 : val);
 *     this.left = (left === undefined ? null : left);
 *     this.right = (right === undefined ? null : right);
 * }
 */
var buildTree = function(data) {
    const vals = data ? data.split(",") : [];       // "1,2,null" -> ["1", "2", "null"]
    if (!vals.length || vals[0] === "null") {
        return null;
    }
    const root = new TreeNode(Number(vals[0]));
    const q = [root];                               // 还没接孩子的节点
    let head = 0, i = 1;                            // head 是队头的下标，出队不用真的删
    while (head < q.length && i < vals.length) {
        const node = q[head++];                     // 给它接左、右孩子
        if (vals[i] !== "null") {
            node.left = new TreeNode(Number(vals[i]));
            q.push(node.left);
        }
        i++;
        if (i < vals.length && vals[i] !== "null") {
            node.right = new TreeNode(Number(vals[i]));
            q.push(node.right);
        }
        i++;
    }
    return root;
};

