class Solution:
    def traversals(self, root: Optional[TreeNode]) -> List[List[int]]:
        pre, ino, post = [], [], []
        def dfs(node):
            if not node:
                return
            pre.append(node.val)            # 前序：刚进入这个节点
            dfs(node.left)
            ino.append(node.val)            # 中序：左子树走完了
            dfs(node.right)
            post.append(node.val)           # 后序：两棵子树都走完了
        dfs(root)
        return [pre, ino, post]

