        if (!node) {
            return;
        }
        pre.push_back(node->val);               // 前序：刚进入这个节点
        dfs(node->left);
        ino.push_back(node->val);               // 中序：左子树走完了
        dfs(node->right);
        post.push_back(node->val);              // 后序：两棵子树都走完了
    }

public:
    vector<vector<int>> traversals(TreeNode* root) {
        dfs(root);
        return {pre, ino, post};
    }
};

