func traversals(root *TreeNode) [][]int {
	pre, ino, post := []int{}, []int{}, []int{}
	var dfs func(node *TreeNode)
	dfs = func(node *TreeNode) {
		if node == nil {
			return
		}
		pre = append(pre, node.Val)   // 前序：刚进入这个节点
		dfs(node.Left)
		ino = append(ino, node.Val)   // 中序：左子树走完了
		dfs(node.Right)
		post = append(post, node.Val) // 后序：两棵子树都走完了
	}
	dfs(root)
	return [][]int{pre, ino, post}
}

