        const snapNodes = () => Object.fromEntries(Object.entries(N).map(([k, v]) => [k, { ...v }]));
        const pre = [], ino = [], post = [], path = [], done = new Set();
        const pathEdges = () => {
          const e = [];
          for (let k = 0; k + 1 < path.length; k++) e.push([path[k], path[k + 1]]);
          return e;
        };
        const view = (cur, opts = {}) => {
