public:
    vector<int> inorderTraversal(TreeNode* root) {
        vector<int> res;
        stack<TreeNode*> st;
        TreeNode* cur = root;
        while (cur || !st.empty()) {
            while (cur) {                               // 一路往左走，沿途的节点压栈
                st.push(cur);
                cur = cur->left;
            }
            cur = st.top();                             // 左边到头了，弹出来访问
            st.pop();
            res.push_back(cur->val);
            cur = cur->right;                           // 再去它的右子树
        }
        return res;
    }
};

