class Solution:
    def largestValues(self, root: Optional[TreeNode]) -> List[int]:
        res = []
        q = deque([root]) if root else deque()
        while q:
            best = q[0].val
            for _ in range(len(q)):             # 这一层有 len(q) 个节点
                node = q.popleft()
                best = max(best, node.val)
                if node.left:
                    q.append(node.left)
                if node.right:
                    q.append(node.right)
            res.append(best)
        return res

java.code:
class Solution {
    public List<Integer> largestValues(TreeNode root) {
        List<Integer> res = new ArrayList<>();
        Deque<TreeNode> q = new ArrayDeque<>();
        if (root != null) {
            q.offer(root);
        }
        while (!q.isEmpty()) {
            int best = q.peek().val;
            for (int n = q.size(); n > 0; n--) {    // 这一层有 q.size() 个节点
                TreeNode node = q.poll();
                best = Math.max(best, node.val);
                if (node.left != null) {
                    q.offer(node.left);
                }
                if (node.right != null) {
                    q.offer(node.right);
                }
            }
            res.add(best);
        }
        return res;
    }
}

