class Solution {
public:
    vector<int> largestValues(TreeNode* root) {
        vector<int> res;
        queue<TreeNode*> q;
        if (root) {
            q.push(root);
        }
        while (!q.empty()) {
            int best = q.front()->val;
            for (int n = q.size(); n > 0; n--) {    // 这一层有 q.size() 个节点
                TreeNode* node = q.front();
                q.pop();
                best = max(best, node->val);
                if (node->left) {
                    q.push(node->left);
                }
                if (node->right) {
                    q.push(node->right);
                }
            }
            res.push_back(best);
        }
        return res;
    }
};

