	}
	for len(q) > 0 {
		best := q[0].Val
		for n := len(q); n > 0; n-- { // 这一层有 len(q) 个节点
			node := q[0]
			q = q[1:]
			if node.Val > best {
				best = node.Val
			}
			if node.Left != nil {
				q = append(q, node.Left)
			}
			if node.Right != nil {
				q = append(q, node.Right)
			}
